import { expect, test, uniqueName } from "../../fixtures";

test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const createRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Audit Vendor"),
      category: "services",
      contact_email: `ap.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@example.com`,
    },
  });
  expect(createRes.status(), await createRes.text()).toBe(201);
  const vendor = await createRes.json();

  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "w9.pdf",
        mimeType: "application/pdf",
        buffer: Buffer.from("%PDF-1.4\n% audit test w9\n%%EOF\n"),
      },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);

  // Background extraction: wait until the extraction event lands in the trail.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/audit`);
        if (res.status() !== 200) return `status ${res.status()}`;
        const body = (await res.json()) as { items: { action: string }[] };
        return body.items.map((e) => e.action).includes("document.extracted");
      },
      { timeout: 60_000 },
    )
    .toBe(true);

  // Act
  const response = await member.get(`/api/vendors/${vendor.id}/audit`);

  // Assert
  expect(response.status(), await response.text()).toBe(200);
  const { items } = (await response.json()) as {
    items: { action: string; at: string; actor: { id: string; name: string; email: string } }[];
  };

  expect(items.map((e) => e.action)).toEqual([
    "vendor.created",
    "document.uploaded",
    "document.extracted",
  ]);

  for (const event of items) {
    expect(event.actor.id, "actor id").toBeTruthy();
    expect(event.actor.name, "actor name").toBeTruthy();
    expect(event.actor.email, "actor email").toBe("member@northwind.test");
    expect(Number.isNaN(Date.parse(event.at)), `timestamp ${event.at}`).toBe(false);
  }

  const times = items.map((e) => Date.parse(e.at));
  for (let i = 1; i < times.length; i++) {
    expect(times[i], "events must be oldest first").toBeGreaterThanOrEqual(times[i - 1]);
  }
});
